// Settings come from the summers.datastore.config.keys data table: { CATEGORY: { key: value } }.
const parse = v => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (/^(true|false)$/i.test(s)) return s.toLowerCase() === 'true';
  if (/^-?\d+(\.\d+)?$/.test(s)) return Number(s);
  if (/^[\[{]/.test(s)) { try { return JSON.parse(s); } catch (e) { /* keep as text */ } }
  return s;
};
const cfg = {};
for (const { json: r } of $input.all()) {
  if (!r || !r.category || !r.key) continue;
  (cfg[r.category] ||= {})[r.key] = parse(r.value);
}
// Fail loudly if a required setting is missing, rather than running with a guess.
const REQUIRED = ["EMAIL_CONFIG.statement_notify_to", "EMAIL_CONFIG.exception_notify_to"];
const missing = REQUIRED.filter(p => { const [c, k] = p.split('.'); const v = cfg[c]?.[k]; return v === undefined || v === null || v === ''; });
if (missing.length) throw new Error('Missing settings in summers.datastore.config.keys: ' + missing.join(', '));
return [{ json: { cfg } }];

const items = $input.all();

// Include invoices from ALL locations
const invoices = items.map(item => item.json);

const escapeHtml = value =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

function getOutcome(invoice) {
  const status = String(invoice.processing_status ?? '').trim();
  const exception = String(invoice.exception_reason ?? '').trim();
  const billId = String(invoice.sage_bill_id ?? '').trim();

  if (exception) {
    return `Error: ${exception}`;
  }

  if (/fail|error|exception/i.test(status)) {
    return `Error: ${status}`;
  }

  if (/duplicate/i.test(status)) {
    return `Duplicate: ${status}`;
  }

  if (
    billId &&
    /success|processed|posted|completed/i.test(status)
  ) {
    return `Processed successfully — Sage Bill ID: ${billId}`;
  }

  if (billId && !status) {
    return `Review required: Sage Bill ID exists, but status is empty`;
  }

  if (status) {
    return `Not confirmed: ${status}`;
  }

  return 'Error: Processing status, exception reason, and Sage Bill ID are empty';
}

function isSuccessful(invoice) {
  const status = String(invoice.processing_status ?? '').trim();
  const exception = String(invoice.exception_reason ?? '').trim();
  const billId = String(invoice.sage_bill_id ?? '').trim();

  return Boolean(
    billId &&
    !exception &&
    /success|processed|posted|completed/i.test(status) &&
    !/fail|error|exception|duplicate/i.test(status)
  );
}

const processed = invoices.filter(isSuccessful);

const errors = invoices.filter(invoice => {
  const outcome = getOutcome(invoice);
  return outcome.startsWith('Error:') ||
         outcome.startsWith('Not confirmed:') ||
         outcome.startsWith('Review required:');
});

const rows = invoices.map(invoice => {
  const outcome = getOutcome(invoice);
  const successful = isSuccessful(invoice);

  return `
    <tr>
      <td>${escapeHtml(invoice.invoice_number || 'N/A')}</td>
      <td>${escapeHtml(invoice.vendor_name || 'N/A')}</td>
      <td>${escapeHtml(invoice.po_number || 'N/A')}</td>
      <td>${escapeHtml(invoice.location_name || 'N/A')}</td>
      <td>${escapeHtml(invoice.total_amount ?? 'N/A')}</td>
      <td>${escapeHtml(invoice.processing_status || 'Empty')}</td>
      <td>${escapeHtml(invoice.exception_reason || 'None')}</td>
      <td>${escapeHtml(invoice.sage_bill_id || 'None')}</td>
      <td style="color:${successful ? '#18794e' : '#b42318'}">
        ${escapeHtml(outcome)}
      </td>
    </tr>`;
}).join('');

const reportDate = new Date().toLocaleDateString('en-CA', {
  timeZone: 'Asia/Kolkata'
});

const html = `
<div style="font-family:Arial,sans-serif;color:#222">
  <h2>Invoice Processing Report — All Locations</h2>
  <p><b>Report date:</b> ${escapeHtml(reportDate)}</p>

  <table cellpadding="10" cellspacing="0"
    style="border-collapse:collapse;width:100%;margin-bottom:20px"
    border="1">
    <tr>
      <th align="left">Metric</th>
      <th align="right">Count</th>
    </tr>
    <tr>
      <td>Total invoices received</td>
      <td align="right">${invoices.length}</td>
    </tr>
    <tr>
      <td>Successfully processed and confirmed in Sage</td>
      <td align="right">${processed.length}</td>
    </tr>
    <tr>
      <td>Errors / outcomes requiring attention</td>
      <td align="right">${errors.length}</td>
    </tr>
  </table>

  <h3>Invoice Details</h3>
  <table cellpadding="7" cellspacing="0"
    style="border-collapse:collapse;width:100%;font-size:12px"
    border="1">
    <thead style="background:#eeeeee">
      <tr>
        <th>Invoice Number</th>
        <th>Vendor</th>
        <th>PO Number</th>
        <th>Location</th>
        <th>Amount</th>
        <th>Processing Status</th>
        <th>Exception Reason</th>
        <th>Sage Bill ID</th>
        <th>Outcome</th>
      </tr>
    </thead>
    <tbody>
      ${rows || '<tr><td colspan="9">No invoices found.</td></tr>'}
    </tbody>
  </table>

  <p style="font-size:12px;color:#666">
    Successful processing is counted only when the status indicates success
    and a Sage Bill ID is recorded. Empty or inconsistent results require review.
  </p>
</div>`;

return [{
  json: {
    report_date: reportDate,
    total_received: invoices.length,
    total_processed: processed.length,
    total_errors: errors.length,
    subject: `Invoice Processing Report - ${reportDate}`,
    html
  }
}];
